CREATE TYPE "Role" AS ENUM ('PASSENGER', 'DRIVER');
CREATE TYPE "RideStatus" AS ENUM ('ACTIVE', 'CANCELLED', 'COMPLETED');
CREATE TYPE "BookingStatus" AS ENUM ('PENDING', 'ACCEPTED', 'REJECTED', 'CANCELLED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'PASSENGER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Vehicle" ("id" TEXT NOT NULL, "driverId" TEXT NOT NULL, "model" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'Sedan', "capacity" INTEGER NOT NULL, CONSTRAINT "Vehicle_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Ride" ("id" TEXT NOT NULL, "driverId" TEXT NOT NULL, "vehicleId" TEXT, "originName" TEXT NOT NULL, "destinationName" TEXT NOT NULL, "originLatitude" DOUBLE PRECISION NOT NULL, "originLongitude" DOUBLE PRECISION NOT NULL, "destinationLatitude" DOUBLE PRECISION NOT NULL, "destinationLongitude" DOUBLE PRECISION NOT NULL, "departureTime" TIMESTAMP(3) NOT NULL, "availableSeats" INTEGER NOT NULL, "price" DECIMAL(8,2) NOT NULL, "status" "RideStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Ride_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Booking" ("id" TEXT NOT NULL, "rideId" TEXT NOT NULL, "passengerId" TEXT NOT NULL, "status" "BookingStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Booking_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DriverLocation" ("id" TEXT NOT NULL, "driverId" TEXT NOT NULL, "latitude" DOUBLE PRECISION NOT NULL, "longitude" DOUBLE PRECISION NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DriverLocation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL, "bookingId" TEXT NOT NULL, "senderId" TEXT NOT NULL, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Vehicle_driverId_key" ON "Vehicle"("driverId");
CREATE INDEX "Ride_originName_destinationName_departureTime_status_idx" ON "Ride"("originName", "destinationName", "departureTime", "status");
CREATE INDEX "Ride_driverId_status_idx" ON "Ride"("driverId", "status");
CREATE INDEX "Booking_rideId_passengerId_status_idx" ON "Booking"("rideId", "passengerId", "status");
CREATE INDEX "Booking_passengerId_status_idx" ON "Booking"("passengerId", "status");
CREATE UNIQUE INDEX "DriverLocation_driverId_key" ON "DriverLocation"("driverId");
CREATE INDEX "Message_bookingId_createdAt_idx" ON "Message"("bookingId", "createdAt");
ALTER TABLE "Vehicle" ADD CONSTRAINT "Vehicle_driverId_fkey" FOREIGN KEY ("driverId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Ride" ADD CONSTRAINT "Ride_driverId_fkey" FOREIGN KEY ("driverId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Ride" ADD CONSTRAINT "Ride_vehicleId_fkey" FOREIGN KEY ("vehicleId") REFERENCES "Vehicle"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_rideId_fkey" FOREIGN KEY ("rideId") REFERENCES "Ride"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_passengerId_fkey" FOREIGN KEY ("passengerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DriverLocation" ADD CONSTRAINT "DriverLocation_driverId_fkey" FOREIGN KEY ("driverId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
